          if(!await ask(info.server+'\n계정 '+info.owner+'\n'+info.names.join(', ')+'\n추출 텍스트 '+info.bytes+' bytes를 서버 메모로 게시할까요? 원본 파일 자체는 전송하지 않습니다.'))return;
